class ToggleDelegate : public QStyledItemDelegate {          // consumer's markup
public:
    void paint(QPainter *p, const QStyleOptionViewItem &o,
               const QModelIndex &i) const override {
        QStyleOptionViewItem opt = o;
        initStyleOption(&opt, i);                            // framework-assembled state
        if (i.data(Qt::UserRole).toBool()) opt.text += "  (on)";
        QStyledItemDelegate::paint(p, opt, i);               // style-aware base painting
    }
};

