class Toggle {                                     // behaviour: owns the state
public:
    using Render = std::function<void(bool on, std::function<void()> toggle)>;
    explicit Toggle(Render r, bool on = false) : r_(std::move(r)), on_(on) {}
    void toggle() { on_ = !on_; }                  // transitions
    void view() const { r_(on_, [this] { const_cast<Toggle *>(this)->toggle(); }); }
private:
    Render r_; bool on_;
};
